package com.sigurd.enemyattackhighlighter;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("enemyattackhighlighter")
public interface EnemyAttackHighlighterConfig extends Config
{
	@ConfigItem(
		keyName = "highlightMode",
		name = "Highlight mode",
		description = "Choose whether to draw outlines, tiles, or both",
		position = 0
	)
	default HighlightMode highlightMode()
	{
		return HighlightMode.BOTH;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used for highlighted attackers",
		position = 1
	)
	default Color highlightColor()
	{
		return new Color(255, 80, 80, 180);
	}

	@ConfigItem(
		keyName = "multicombatOnly",
		name = "Multicombat only",
		description = "Only tag/highlight NPCs while in multicombat zones",
		position = 2
	)
	default boolean multicombatOnly()
	{
		return false;
	}

	@Range(
		min = 0,
		max = 600
	)
	@ConfigItem(
		keyName = "tagDurationSeconds",
		name = "Tag duration (seconds)",
		description = "How long tags persist; set to 0 to keep tags until death/despawn",
		position = 3
	)
	default int tagDurationSeconds()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "debugTaggedNpcs",
		name = "Debug tagged NPCs",
		description = "Show debug text above tagged NPCs",
		position = 4
	)
	default boolean debugTaggedNpcs()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableWhitelist",
		name = "Enable whitelist",
		description = "Only tag NPCs listed in the whitelist CSV",
		position = 5
	)
	default boolean enableWhitelist()
	{
		return false;
	}

	@ConfigItem(
		keyName = "whitelistCsv",
		name = "Whitelist (CSV)",
		description = "Comma-separated NPC names, e.g. goblin, dust devil",
		position = 6
	)
	default String whitelistCsv()
	{
		return "";
	}

	@Range(
		min = 1,
		max = 64
	)
	@ConfigItem(
		keyName = "rangeTiles",
		name = "Range tiles",
		description = "Max distance before NPC is considered out of range",
		position = 7
	)
	default int rangeTiles()
	{
		return 15;
	}

	@Range(
		min = 1,
		max = 120
	)
	@ConfigItem(
		keyName = "outOfRangeSeconds",
		name = "Out of range seconds",
		description = "How long NPC can stay out of range before tag is removed",
		position = 8
	)
	default int outOfRangeSeconds()
	{
		return 3;
	}

}

package com.sigurd.enemyattackhighlighter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class EnemyAttackHighlighterOverlay extends Overlay
{
	private final Client client;
	private final EnemyAttackHighlighterPlugin plugin;
	private final EnemyAttackHighlighterConfig config;

	@Inject
	public EnemyAttackHighlighterOverlay(
		Client client,
		EnemyAttackHighlighterPlugin plugin,
		EnemyAttackHighlighterConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Set<NPC> attackers = plugin.getAttackers();
		if (attackers.isEmpty())
		{
			return null;
		}

		HighlightMode mode = config.highlightMode();
		Color color = config.highlightColor();

		for (NPC npc : attackers)
		{
			if (npc == null)
			{
				continue;
			}

			if (mode == HighlightMode.OUTLINE || mode == HighlightMode.BOTH)
			{
				Shape hull = npc.getConvexHull();
				if (hull != null)
				{
					graphics.setStroke(new BasicStroke(2));
					OverlayUtil.renderPolygon(graphics, hull, color);
				}
			}

			if (mode == HighlightMode.TILE || mode == HighlightMode.BOTH)
			{
				LocalPoint lp = npc.getLocalLocation();
				if (lp == null)
				{
					continue;
				}

				Polygon tile = Perspective.getCanvasTilePoly(client, lp);
				if (tile != null)
				{
					OverlayUtil.renderPolygon(graphics, tile, color);
				}
			}

			if (config.debugTaggedNpcs())
			{
				String npcName = npc.getName() == null ? "Unknown NPC" : npc.getName();
				int secondsRemaining = plugin.getSecondsRemaining(npc);
				int cooldownRemaining = plugin.getRetagCooldownRemainingSeconds(npc);
				String cooldownText = cooldownRemaining < 0 ? "lock" : cooldownRemaining + "s";
				String timerText = secondsRemaining < 0 ? "inf" : secondsRemaining + "s";
				String label = "Tagged: " + npcName + " (" + timerText + ", cd:" + cooldownText + ")";
				Point textLocation = Perspective.getCanvasTextLocation(
					client,
					graphics,
					npc.getLocalLocation(),
					label,
					npc.getLogicalHeight() + 40
				);
				if (textLocation != null)
				{
					OverlayUtil.renderTextLocation(graphics, textLocation, label, color);
				}
			}
		}

		return null;
	}
}

package com.sigurd.enemyattackhighlighter;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Locale;
import java.util.Set;
import java.util.WeakHashMap;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Enemy Attack Highlighter",
	description = "Highlights NPCs you have tagged",
	tags = {"npc", "combat", "highlight", "attackers", "aggro"}
)
public class EnemyAttackHighlighterPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private EnemyAttackHighlighterConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EnemyAttackHighlighterOverlay overlay;

	private final Set<NPC> taggedNpcs = new HashSet<>();
	private final Map<NPC, Integer> taggedAtTick = new WeakHashMap<>();
	private final Map<NPC, Integer> lastTagTick = new WeakHashMap<>();
	private final Map<NPC, Integer> outOfRangeSinceTick = new WeakHashMap<>();
	private int tickCount = 0;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clearTags();
		log.debug("Enemy Attack Highlighter started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clearTags();
		log.debug("Enemy Attack Highlighter stopped");
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		removeTag(event.getNpc());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!isPluginActiveInCurrentZone())
		{
			return;
		}

		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		if (event.getHitsplat() == null || !event.getHitsplat().isMine())
		{
			return;
		}

		addTag((NPC) event.getActor());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			clearTags();
			return;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		tickCount++;
		cleanupTags();
	}

	Set<NPC> getAttackers()
	{
		return Collections.unmodifiableSet(taggedNpcs);
	}

	int getSecondsRemaining(NPC npc)
	{
		int durationSeconds = config.tagDurationSeconds();
		if (durationSeconds <= 0)
		{
			return -1;
		}

		Integer taggedTick = taggedAtTick.get(npc);
		if (taggedTick == null)
		{
			return 0;
		}

		int durationTicks = durationSecondsToTicks(durationSeconds);
		int remainingTicks = Math.max(0, durationTicks - (tickCount - taggedTick));
		return (int) Math.ceil(remainingTicks * 0.6d);
	}

	int getRetagCooldownSeconds()
	{
		int durationSeconds = config.tagDurationSeconds();
		if (durationSeconds <= 0)
		{
			return -1;
		}

		return durationSeconds / 2;
	}

	int getRetagCooldownRemainingSeconds(NPC npc)
	{
		int cooldownSeconds = getRetagCooldownSeconds();
		if (cooldownSeconds < 0)
		{
			return taggedNpcs.contains(npc) ? -1 : 0;
		}

		if (cooldownSeconds == 0)
		{
			return 0;
		}

		Integer lastTick = lastTagTick.get(npc);
		if (lastTick == null)
		{
			return 0;
		}

		int cooldownTicks = durationSecondsToTicks(cooldownSeconds);
		int remainingTicks = Math.max(0, cooldownTicks - (tickCount - lastTick));
		return (int) Math.ceil(remainingTicks * 0.6d);
	}

	private void addTag(NPC npc)
	{
		if (npc == null || npc.isDead())
		{
			return;
		}

		if (!isNpcAllowedByWhitelist(npc))
		{
			return;
		}

		if (isNpcOutOfRange(npc))
		{
			return;
		}

		if (isRetagOnCooldown(npc))
		{
			return;
		}

		taggedNpcs.add(npc);
		taggedAtTick.put(npc, tickCount);
		lastTagTick.put(npc, tickCount);
		outOfRangeSinceTick.remove(npc);
	}

	private void removeTag(NPC npc)
	{
		taggedNpcs.remove(npc);
		taggedAtTick.remove(npc);
		outOfRangeSinceTick.remove(npc);
	}

	private void clearTags()
	{
		taggedNpcs.clear();
		taggedAtTick.clear();
		outOfRangeSinceTick.clear();
	}

	private void cleanupTags()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			clearTags();
			return;
		}

		if (!isPluginActiveInCurrentZone())
		{
			clearTags();
			return;
		}

		Iterator<NPC> iterator = taggedNpcs.iterator();
		while (iterator.hasNext())
		{
			NPC npc = iterator.next();
			if (npc == null || npc.isDead())
			{
				iterator.remove();
				removeTagState(npc);
				continue;
			}

			if (!isNpcAllowedByWhitelist(npc))
			{
				iterator.remove();
				removeTagState(npc);
				continue;
			}

			if (isOutOfRangeExpired(npc))
			{
				iterator.remove();
				removeTagState(npc);
				continue;
			}

			if (isTagExpired(npc))
			{
				iterator.remove();
				removeTagState(npc);
			}
		}
	}

	private void removeTagState(NPC npc)
	{
		taggedAtTick.remove(npc);
		outOfRangeSinceTick.remove(npc);
	}

	private boolean isTagExpired(NPC npc)
	{
		int durationSeconds = config.tagDurationSeconds();
		if (durationSeconds <= 0)
		{
			return false;
		}

		Integer taggedTick = taggedAtTick.get(npc);
		if (taggedTick == null)
		{
			return true;
		}

		return tickCount - taggedTick >= durationSecondsToTicks(durationSeconds);
	}

	private int durationSecondsToTicks(int durationSeconds)
	{
		return Math.max(1, (int) Math.ceil(durationSeconds / 0.6d));
	}

	private boolean isRetagOnCooldown(NPC npc)
	{
		int cooldownSeconds = getRetagCooldownSeconds();
		if (cooldownSeconds < 0)
		{
			return taggedNpcs.contains(npc);
		}

		if (cooldownSeconds == 0)
		{
			return false;
		}

		Integer lastTick = lastTagTick.get(npc);
		if (lastTick == null)
		{
			return false;
		}

		return tickCount - lastTick < durationSecondsToTicks(cooldownSeconds);
	}

	private boolean isOutOfRangeExpired(NPC npc)
	{
		if (!isNpcOutOfRange(npc))
		{
			outOfRangeSinceTick.remove(npc);
			return false;
		}

		Integer outSince = outOfRangeSinceTick.get(npc);
		if (outSince == null)
		{
			outOfRangeSinceTick.put(npc, tickCount);
			return false;
		}

		return tickCount - outSince >= durationSecondsToTicks(config.outOfRangeSeconds());
	}

	private boolean isNpcOutOfRange(NPC npc)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return false;
		}

		LocalPoint playerLocation = localPlayer.getLocalLocation();
		LocalPoint npcLocation = npc.getLocalLocation();
		if (playerLocation == null || npcLocation == null)
		{
			return true;
		}

		int deltaX = Math.abs(playerLocation.getX() - npcLocation.getX()) / 128;
		int deltaY = Math.abs(playerLocation.getY() - npcLocation.getY()) / 128;
		int tileDistance = Math.max(deltaX, deltaY);
		return tileDistance > config.rangeTiles();
	}

	private boolean isPluginActiveInCurrentZone()
	{
		if (!config.multicombatOnly())
		{
			return true;
		}

		return client.getVarbitValue(Varbits.MULTICOMBAT_AREA) == 1;
	}

	private boolean isNpcAllowedByWhitelist(NPC npc)
	{
		if (!config.enableWhitelist())
		{
			return true;
		}

		String npcName = normalizeName(npc.getName());
		if (npcName.isEmpty())
		{
			return false;
		}

		String whitelistCsv = config.whitelistCsv();
		if (whitelistCsv == null || whitelistCsv.trim().isEmpty())
		{
			return false;
		}

		for (String rawEntry : whitelistCsv.split(","))
		{
			String entry = normalizeName(rawEntry);
			if (!entry.isEmpty() && entry.equals(npcName))
			{
				return true;
			}
		}

		return false;
	}

	private String normalizeName(String name)
	{
		if (name == null)
		{
			return "";
		}

		return name.trim().toLowerCase(Locale.ENGLISH);
	}

	@Provides
	EnemyAttackHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EnemyAttackHighlighterConfig.class);
	}
}

package com.sigurd.enemyattackhighlighter;

public enum HighlightMode
{
	OUTLINE,
	TILE,
	BOTH
}

package com.sigurd.enemyattackhighlighter;

